#include <stdio.h>
#include <stdlib.h>

typedef struct Node {          // tag "Node" is required to refer to itself
    int value;
    struct Node *next;         // note: "struct Node", the typedef isn't ready yet
} Node;

int main(void) {
    Node *head = NULL;

    // Build 3 -> 2 -> 1 by pushing onto the front
    for (int i = 1; i <= 3; i++) {
        Node *n = malloc(sizeof *n);
        if (n == NULL) return 1;
        n->value = i;
        n->next  = head;
        head = n;
    }

    for (Node *cur = head; cur != NULL; cur = cur->next) {
        printf("%d -> ", cur->value);
    }
    printf("NULL\n");

    // Free the list: save "next" BEFORE freeing the node
    Node *cur = head;
    while (cur != NULL) {
        Node *next = cur->next;
        free(cur);
        cur = next;
    }
    return 0;
}
// Output:
// 3 -> 2 -> 1 -> NULL

