double average(const int *values, int n) {
    // assert documents an assumption the CALLER must satisfy.
    // Compiled out entirely when NDEBUG is defined (gcc -DNDEBUG).
    assert(values != NULL);
    assert(n > 0);

    long sum = 0;
    for (int i = 0; i < n; i++) sum += values[i];
    return (double)sum / n;
}

