}

// stack.c
#include <stdio.h>

#define STACK_CAP 8

typedef struct {
    int data[STACK_CAP];
    int top;   // index of the next free slot; 0 means empty
} Stack;

void stack_init(Stack *s) {
    s->top = 0;
}

int stack_push(Stack *s, int value) {
    if (s->top >= STACK_CAP) {
        return 0;   // full
    }
    s->data[s->top] = value;
    s->top++;
    return 1;
}

int stack_pop(Stack *s, int *out) {
    if (s->top == 0) {
        return 0;   // empty
    }
    s->top--;
    *out = s->data[s->top];
    return 1;
}

int main(void) {
    Stack s;
    stack_init(&s);

    stack_push(&s, 1);
    stack_push(&s, 2);
    stack_push(&s, 3);

    int value;
    while (stack_pop(&s, &value)) {
        printf("popped %d\n", value);
    }

    if (!stack_pop(&s, &value)) {
        printf("stack is empty\n");
    }
    return 0;
}

// queue.c
#include <stdio.h>

#define QUEUE_CAP 4

typedef struct {
    int data[QUEUE_CAP];
    int head;   // index of the oldest element
    int count;  // number of elements currently stored
} Queue;

void queue_init(Queue *q) {
    q->head = 0;
    q->count = 0;
}

int queue_enqueue(Queue *q, int value) {
    if (q->count == QUEUE_CAP) {
        return 0;   // full
    }
    int tail = (q->head + q->count) % QUEUE_CAP;
    q->data[tail] = value;
    q->count++;
    return 1;
}

int queue_dequeue(Queue *q, int *out) {
    if (q->count == 0) {
        return 0;   // empty
    }
    *out = q->data[q->head];
    q->head = (q->head + 1) % QUEUE_CAP;
    q->count--;
    return 1;
}

int main(void) {
    Queue q;
    queue_init(&q);

    queue_enqueue(&q, 100);
    queue_enqueue(&q, 200);
    queue_enqueue(&q, 300);

    int value;
    queue_dequeue(&q, &value);
    printf("dequeued %d\n", value);

    // Enqueue two more -- this wraps the circular buffer past the end of data[]
    queue_enqueue(&q, 400);
    queue_enqueue(&q, 500);

    while (queue_dequeue(&q, &value)) {
        printf("dequeued %d\n", value);
    }
    return 0;
}

// bst.c
#include <stdio.h>
#include <stdlib.h>

typedef struct TreeNode {
    int value;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

TreeNode *tree_insert(TreeNode *root, int value) {
    if (root == NULL) {
        TreeNode *n = malloc(sizeof(TreeNode));
        if (!n) { fprintf(stderr, "out of memory\n"); exit(1); }
        n->value = value;
        n->left = n->right = NULL;
        return n;
    }
    if (value < root->value) {
        root->left = tree_insert(root->left, value);
    } else if (value > root->value) {
        root->right = tree_insert(root->right, value);
    }
    // equal values are ignored -- no duplicates in this tree
    return root;
}

TreeNode *tree_find(TreeNode *root, int value) {
    if (root == NULL || root->value == value) {
        return root;
    }
    if (value < root->value) {
        return tree_find(root->left, value);
    }
    return tree_find(root->right, value);
}

void tree_print_inorder(const TreeNode *root) {
    if (root == NULL) return;
    tree_print_inorder(root->left);
    printf("%d ", root->value);
    tree_print_inorder(root->right);
}

void tree_free(TreeNode *root) {
    if (root == NULL) return;
    tree_free(root->left);
    tree_free(root->right);
    free(root);
}

int main(void) {
    TreeNode *root = NULL;
    int values[] = {50, 30, 70, 20, 40, 60, 80};
    for (size_t i = 0; i < sizeof(values) / sizeof(values[0]); i++) {
        root = tree_insert(root, values[i]);
    }

    printf("in-order: ");
    tree_print_inorder(root);
    printf("\n");

    int target = 40;
    TreeNode *found = tree_find(root, target);
    printf("find(%d): %s\n", target, found ? "found" : "not found");

    target = 99;
    found = tree_find(root, target);
    printf("find(%d): %s\n", target, found ? "found" : "not found");

    tree_free(root);
    return 0;
}

// graph_bfs.c
#include <stdio.h>
#include <stdlib.h>

#define MAX_VERTICES 6

typedef struct EdgeNode {
    int dest;
    struct EdgeNode *next;
} EdgeNode;

typedef struct {
    EdgeNode *adj[MAX_VERTICES];   // one linked list of neighbors per vertex
    int num_vertices;
} Graph;

void graph_init(Graph *g, int num_vertices) {
    g->num_vertices = num_vertices;
    for (int i = 0; i < num_vertices; i++) {
        g->adj[i] = NULL;
    }
}

void graph_add_edge(Graph *g, int src, int dest) {
    // undirected: add dest to src's list, and src to dest's list
    EdgeNode *n1 = malloc(sizeof(EdgeNode));
    n1->dest = dest;
    n1->next = g->adj[src];
    g->adj[src] = n1;

    EdgeNode *n2 = malloc(sizeof(EdgeNode));
    n2->dest = src;
    n2->next = g->adj[dest];
    g->adj[dest] = n2;
}

void graph_bfs(const Graph *g, int start) {
    int visited[MAX_VERTICES] = {0};
    int queue[MAX_VERTICES];
    int head = 0, tail = 0;

    visited[start] = 1;
    queue[tail++] = start;

    printf("BFS from %d: ", start);
    while (head < tail) {
        int current = queue[head++];
        printf("%d ", current);

        for (EdgeNode *e = g->adj[current]; e != NULL; e = e->next) {
            if (!visited[e->dest]) {
                visited[e->dest] = 1;
                queue[tail++] = e->dest;
            }
        }
    }
    printf("\n");
}

void graph_free(Graph *g) {
    for (int i = 0; i < g->num_vertices; i++) {
        EdgeNode *cur = g->adj[i];
        while (cur != NULL) {
            EdgeNode *next = cur->next;
            free(cur);
            cur = next;
        }
    }
}

int main(void) {
    Graph g;
    graph_init(&g, 6);

    //    0 -- 1 -- 3
    //    |    |
    //    2    4 -- 5
    graph_add_edge(&g, 0, 1);
    graph_add_edge(&g, 0, 2);
    graph_add_edge(&g, 1, 3);
    graph_add_edge(&g, 1, 4);
    graph_add_edge(&g, 4, 5);

    graph_bfs(&g, 0);

    graph_free(&g);
    return 0;
}

// quicksort.c
#include <stdio.h>

void swap(int *a, int *b) {
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

int partition(int arr[], int low, int high) {
    int pivot = arr[high];   // last element as pivot
    int i = low - 1;         // boundary of "smaller than pivot" region

    for (int j = low; j < high; j++) {
        if (arr[j] < pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return i + 1;             // pivot's final index
}

void quicksort(int arr[], int low, int high) {
    if (low < high) {
        int pivot_index = partition(arr, low, high);
        quicksort(arr, low, pivot_index - 1);
        quicksort(arr, pivot_index + 1, high);
    }
}

void print_array(const int arr[], int n) {
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

int main(void) {
    int data[] = {9, 3, 7, 1, 8, 2, 5, 4, 6};
    int n = sizeof(data) / sizeof(data[0]);

    printf("before: ");
    print_array(data, n);

    quicksort(data, 0, n - 1);

    printf("after:  ");
    print_array(data, n);
    return 0;
}

// (append to quicksort.c)
int binary_search(const int arr[], int n, int target) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;   // avoids overflow vs (low+high)/2
        if (arr[mid] == target) {
            return mid;
        } else if (arr[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}

int main(void) {
    /* ... quicksort as above ... */
    int target = 7;
    int idx = binary_search(data, n, target);
    printf("binary_search(%d) = index %d\n", target, idx);

    target = 42;
    idx = binary_search(data, n, target);
    printf("binary_search(%d) = index %d\n", target, idx);
    return 0;
}

