// bits1.c
#include <stdio.h>

#define BIT(n) (1u << (n))

int main(void) {
    unsigned int flags = 0;

    flags |= BIT(1);   // set bit 1
    flags |= BIT(3);   // set bit 3
    printf("after setting bits 1,3: 0x%02X\n", flags);

    flags &= ~BIT(1);  // clear bit 1
    printf("after clearing bit 1:   0x%02X\n", flags);

    flags ^= BIT(3);   // toggle bit 3 (was set, becomes clear)
    printf("after toggling bit 3:   0x%02X\n", flags);

    flags ^= BIT(3);   // toggle again (clear -> set)
    printf("after toggling bit 3 again: 0x%02X\n", flags);

    int is_set = (flags & BIT(3)) != 0;
    printf("is bit 3 set? %s\n", is_set ? "yes" : "no");

    return 0;
}

// bits2.c -- shifting, sign extension, and Brian Kernighan's popcount
#include <stdio.h>

int count_bits_naive(unsigned int n) {
    int count = 0;
    while (n) {
        count += (n & 1);
        n >>= 1;
    }
    return count;
}

int count_bits_kernighan(unsigned int n) {
    int count = 0;
    while (n) {
        n &= (n - 1);   // clears the lowest set bit each time
        count++;
    }
    return count;
}

int main(void) {
    unsigned int x = 0b10110100;
    printf("x = 0x%02X, naive popcount = %d, kernighan popcount = %d\n",
           x, count_bits_naive(x), count_bits_kernighan(x));

    int signed_val = -8;              // 0xFFFFFFF8 in two's complement
    printf("\n-8 >> 1 (signed, arithmetic shift): %d\n", signed_val >> 1);

    unsigned int unsigned_val = (unsigned int)signed_val;
    printf("-8 reinterpreted as unsigned >> 1 (logical shift): %u\n",
           unsigned_val >> 1);

    unsigned int one = 1;
    printf("\n1u << 31 = %u\n", one << 31);
    // 1u << 32 would be undefined behavior on a 32-bit unsigned int -- not tested here

    return 0;
}

// endian.c -- detect byte order and pack/unpack a 32-bit value into bytes
#include <stdio.h>
#include <stdint.h>

int is_little_endian(void) {
    uint32_t probe = 1;
    unsigned char *byte0 = (unsigned char *)&probe;
    return *byte0 == 1;   // low-order byte stored first == little-endian
}

void pack_be32(unsigned char out[4], uint32_t value) {
    out[0] = (value >> 24) & 0xFF;
    out[1] = (value >> 16) & 0xFF;
    out[2] = (value >> 8) & 0xFF;
    out[3] = value & 0xFF;
}

uint32_t unpack_be32(const unsigned char in[4]) {
    return ((uint32_t)in[0] << 24) | ((uint32_t)in[1] << 16) |
           ((uint32_t)in[2] << 8) | (uint32_t)in[3];
}

int main(void) {
    printf("this machine is %s-endian\n",
           is_little_endian() ? "little" : "big");

    uint32_t value = 0x11223344;
    unsigned char buf[4];
    pack_be32(buf, value);

    printf("packed big-endian bytes: %02X %02X %02X %02X\n",
           buf[0], buf[1], buf[2], buf[3]);

    uint32_t roundtrip = unpack_be32(buf);
    printf("unpacked value: 0x%08X (%s)\n",
           roundtrip, roundtrip == value ? "matches" : "MISMATCH");

    return 0;
}

// layout.c -- where different kinds of variables actually live
#include <stdio.h>
#include <stdlib.h>

int global_var = 100;             // data segment (initialized global)
static int static_var;            // BSS segment (zero-initialized)

void show_addresses(void) {
    int local_var = 1;            // stack
    int *heap_var = malloc(sizeof(int));
    *heap_var = 1;

    printf("global_var (data):   %p\n", (void *)&global_var);
    printf("static_var (bss):    %p\n", (void *)&static_var);
    printf("local_var (stack):   %p\n", (void *)&local_var);
    printf("heap_var  (heap):    %p\n", (void *)heap_var);

    free(heap_var);
}

int main(void) {
    show_addresses();
    return 0;
}

// realloc_demo.c -- the correct pattern for growing a heap buffer with realloc
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t count = 4;
    int *arr = malloc(count * sizeof(int));
    for (size_t i = 0; i < count; i++) arr[i] = (int)(i + 1);

    printf("before grow: ");
    for (size_t i = 0; i < count; i++) printf("%d ", arr[i]);
    printf("\n");

    size_t new_count = 8;
    int *tmp = realloc(arr, new_count * sizeof(int));
    if (tmp == NULL) {
        fprintf(stderr, "realloc failed, original block still valid\n");
        free(arr);
        return 1;
    }
    arr = tmp;                       // only overwrite arr once realloc succeeded
    for (size_t i = count; i < new_count; i++) arr[i] = (int)(i + 1);
    count = new_count;

    printf("after grow:  ");
    for (size_t i = 0; i < count; i++) printf("%d ", arr[i]);
    printf("\n");

    free(arr);
    return 0;
}

// uaf.c -- use-after-free, caught by AddressSanitizer
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *p = malloc(sizeof(int));
    *p = 42;
    printf("before free: %d\n", *p);

    free(p);
    printf("after free:  %d\n", *p);   // BUG: reads freed memory

    return 0;
}

free(p);
p = NULL;
// ... much later, in a code path that doesn't know p was already freed ...
free(p);   // free(NULL) -- safe no-op, not a crash

