// std::exception                      -- the base class for all standard exceptions
//   +-- std::logic_error               -- errors detectable before running (bad arguments, etc.)
//   |     +-- std::invalid_argument
//   |     +-- std::out_of_range
//   |     +-- std::length_error
//   +-- std::runtime_error             -- errors only detectable at runtime
//         +-- std::overflow_error
