// account.cpp
#include "account.h"
#include <stdexcept>

Account::Account(const std::string& owner, double initialBalance)
    : owner(owner), balance(initialBalance) {
    if (initialBalance < 0) {
        throw std::invalid_argument("Initial balance cannot be negative");
    }
}

void Account::deposit(double amount) {
    if (amount <= 0) {
        throw std::invalid_argument("Deposit amount must be positive");
    }
    balance += amount;
}

void Account::withdraw(double amount) {
    if (amount <= 0) {
        throw std::invalid_argument("Withdrawal amount must be positive");
    }
    if (amount > balance) {
        throw std::runtime_error("Insufficient funds");
    }
    balance -= amount;
}

const std::string& Account::getOwner() const {
    return owner;
}

double Account::getBalance() const {
    return balance;
}

// main.cpp
#include <iostream>
#include <vector>
#include "account.h"

int findAccount(const std::vector<Account>& accounts, const std::string& owner) {
    for (size_t i = 0; i < accounts.size(); i++) {
        if (accounts[i].getOwner() == owner) {
            return static_cast<int>(i);
        }
    }
    return -1;
}

int main() {
    std::vector<Account> accounts;
    int choice = 0;

    do {
        std::cout << "\n1. Open account  2. Deposit  3. Withdraw  4. List  5. Quit\n> ";
        std::cin >> choice;

        try {
            if (choice == 1) {
                std::string owner;
                double balance;
                std::cout << "Owner name: ";
                std::cin >> owner;
                std::cout << "Initial balance: ";
                std::cin >> balance;
                accounts.emplace_back(owner, balance);
                std::cout << "Account opened for " << owner << std::endl;

            } else if (choice == 2 || choice == 3) {
                std::string owner;
                double amount;
                std::cout << "Owner name: ";
                std::cin >> owner;
                std::cout << "Amount: ";
                std::cin >> amount;

                int idx = findAccount(accounts, owner);
                if (idx < 0) {
                    std::cout << "No such account." << std::endl;
                    continue;
                }

                if (choice == 2) {
                    accounts[idx].deposit(amount);
                } else {
                    accounts[idx].withdraw(amount);
                }
                std::cout << "New balance: " << accounts[idx].getBalance() << std::endl;

            } else if (choice == 4) {
                for (const auto& acc : accounts) {
                    std::cout << acc.getOwner() << ": $" << acc.getBalance() << std::endl;
                }
            }
        } catch (const std::exception& e) {
            std::cout << "Error: " << e.what() << std::endl;
        }

    } while (choice != 5);

    std::cout << "Goodbye!" << std::endl;
    return 0;
}

#include <iostream>
#include <string>

class Animal {
public:
    Animal(std::string name) : name(name) {}

    void eat() const {
        std::cout << name << " is eating." << std::endl;
    }

protected:
    std::string name;   // accessible in this class AND in derived classes
};

// Dog "is-a" Animal
class Dog : public Animal {
public:
    Dog(std::string name) : Animal(name) {}   // must initialise the base part

    void bark() const {
        std::cout << name << " says Woof!" << std::endl;   // 'name' is protected, so visible here
    }
};

int main() {
    Dog rex("Rex");
    rex.eat();    // inherited from Animal
    rex.bark();   // Dog's own method
}
// Output:
// Rex is eating.
// Rex says Woof!

#include <iostream>

class Shape {
public:
    virtual double area() const { return 0.0; }   // virtual => runtime dispatch
    void describe() const {                       // NOT virtual
        std::cout << "A generic shape" << std::endl;
    }
    virtual ~Shape() = default;                   // see "the two big traps" below
};

class Circle : public Shape {
public:
    Circle(double r) : r(r) {}
    double area() const override { return 3.14159265 * r * r; }
    void describe() const { std::cout << "A circle" << std::endl; }
private:
    double r;
};

int main() {
    Circle c(2.0);
    Shape& s = c;   // a Shape reference bound to a Circle object

