    // 3. Whole file into one string
    std::ifstream in3("scores.txt");
    std::stringstream buffer;
    buffer << in3.rdbuf();                    // slurp the entire stream buffer
    std::string contents = buffer.str();
    std::cout << contents.size() << " bytes" << std::endl;
}
