    sqlite3_exec(db, "DELETE FROM employees;", nullptr, nullptr, nullptr);   // start clean for the demo

    insertEmployee(db, "Grace Hopper", "Engineering");
    insertEmployee(db, "Ada Lovelace", "Research");

    sqlite3_close(db);
