class Task {
  final String title;
  bool done;

  Task(this.title, {this.done = false});

  // Convert this Task to a simple Map so it can be JSON-encoded
  Map<String, dynamic> toJson() => {
        'title': title,
        'done': done,
      };

  // Rebuild a Task from a decoded JSON Map
  factory Task.fromJson(Map<String, dynamic> json) {
    return Task(json['title'] as String, done: json['done'] as bool);
  }

  @override
  String toString() {
    final marker = done ? '[x]' : '[ ]';
    return '$marker $title';
  }
}

import 'dart:convert';
import 'dart:io';

const _storageFile = 'tasks.json';

List<Task> loadTasks() {
  final file = File(_storageFile);
  if (!file.existsSync()) return [];

  final contents = file.readAsStringSync();
  if (contents.trim().isEmpty) return [];

  final List<dynamic> decoded = jsonDecode(contents);
  return decoded.map((item) => Task.fromJson(item as Map<String, dynamic>)).toList();
}

void saveTasks(List<Task> tasks) {
  final file = File(_storageFile);
  final encoded = jsonEncode(tasks.map((t) => t.toJson()).toList());
  file.writeAsStringSync(encoded);
}

void printUsage() {
  print('''
Usage: dart run bin/todo_cli.dart <command> [args]

Commands:
  add <title>       Add a new task
  list               List all tasks
  done <index>       Mark task at <index> as done
  remove <index>     Remove task at <index>
''');
}

void main(List<String> args) {
  final tasks = loadTasks();

  if (args.isEmpty) {
    printUsage();
    return;
  }

  final command = args[0];

  switch (command) {
    case 'add':
      if (args.length < 2) {
        print('Error: "add" requires a title.');
        return;
      }
      final title = args.sublist(1).join(' ');
      tasks.add(Task(title));
      saveTasks(tasks);
      print('Added: $title');

    case 'list':
      if (tasks.isEmpty) {
        print('No tasks yet. Add one with: add <title>');
        return;
      }
      for (var i = 0; i < tasks.length; i++) {
        print('$i. ${tasks[i]}');
      }

    case 'done':
      final index = _parseIndex(args, tasks.length);
      if (index == null) return;
      tasks[index].done = true;
      saveTasks(tasks);
      print('Marked done: ${tasks[index].title}');

    case 'remove':
      final index = _parseIndex(args, tasks.length);
      if (index == null) return;
      final removed = tasks.removeAt(index);
      saveTasks(tasks);
      print('Removed: ${removed.title}');

    default:
      print('Unknown command: $command');
      printUsage();
  }
}

int? _parseIndex(List<String> args, int taskCount) {
  if (args.length < 2) {
    print('Error: this command requires an index.');
    return null;
  }
  final index = int.tryParse(args[1]);
  if (index == null || index < 0 || index >= taskCount) {
    print('Error: invalid index "${args[1]}".');
    return null;
  }
  return index;
}

abstract class Shape {
  // Abstract classes can hold real state and concrete methods...
  final String label;
  Shape(this.label);

  // ...but a method with no body is abstract: subclasses must implement it.
  double area();

  // Concrete methods can call the abstract ones -- polymorphism at work.
  void describe() {
    print('$label has area ${area().toStringAsFixed(2)}');
  }
}

class Circle extends Shape {
  final double radius;
  Circle(this.radius) : super('Circle');

  @override
  double area() => 3.14159 * radius * radius;
}

class Square extends Shape {
  final double side;
  Square(this.side) : super('Square');

  @override
  double area() => side * side;
}

void main() {
  final shapes = <Shape>[Circle(2), Square(3)];
  for (final shape in shapes) {
    shape.describe();
  }
  // Circle has area 12.57
  // Square has area 9.00

