const uint8_t BUTTON_PIN = 4;
const uint8_t LED_PIN = 5;
const uint32_t DEBOUNCE_MS = 30;

bool ledOn = false;
int lastReading = HIGH;          // raw reading last time we looked
int stableState = HIGH;          // debounced, "official" button state
uint32_t lastChangeMs = 0;

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int reading = digitalRead(BUTTON_PIN);

  if (reading != lastReading) {
    lastChangeMs = millis();     // signal changed — restart the stability timer
    lastReading = reading;
  }

  if (millis() - lastChangeMs > DEBOUNCE_MS && reading != stableState) {
    stableState = reading;       // reading has been stable long enough — accept it
    if (stableState == LOW) {    // falling edge = the moment of the press
      ledOn = !ledOn;            // toggle the LED once per press
      digitalWrite(LED_PIN, ledOn);
    }
  }
}

// Read a potentiometer and print voltage — works on Uno and ESP32
const uint8_t POT_PIN = 34;        // ESP32: use an ADC-capable pin like 32-36; Uno: A0

void setup() {
  Serial.begin(115200);
}

void loop() {
  int raw = analogRead(POT_PIN);   // 0..4095 on ESP32, 0..1023 on Uno

  // Convert to a voltage (ESP32: 3.3V full scale, 4095 steps)
  float volts = raw * 3.3 / 4095.0;

  Serial.print(raw);
  Serial.print(" -> ");
  Serial.print(volts, 2);
  Serial.println(" V");
  delay(200);
}

