	fmt.Println(classify("hi"))           // string of length 2
	fmt.Println(classify([]int{1, 2, 3})) // int slice with 3 elements
	fmt.Println(classify(3.14))           // unhandled type float64
	fmt.Println(classify(nil))            // nil value
}

