var (
	ErrNotFound     = errors.New("record not found")
	ErrUnauthorized = errors.New("unauthorized")
)

var db = map[int]string{1: "Ada", 2: "Grace"}

func lookup(id int, admin bool) (string, error) {
	if !admin {
		return "", ErrUnauthorized
	}
	name, ok := db[id]
	if !ok {
		return "", ErrNotFound
	}
	return name, nil
