package weather

import "testing"

func TestDescribe(t *testing.T) {
	tests := []struct {
		name string
		code int
		want string
	}{
		{"clear", 0, "Clear sky"},
		{"overcast", 3, "Overcast"},
		{"heavy rain", 65, "Heavy rain"},
		{"thunderstorm", 95, "Thunderstorm"},
		{"unmapped code", 12345, "Unknown conditions"},
		{"negative code", -1, "Unknown conditions"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Describe(tt.code); got != tt.want {
				t.Errorf("Describe(%d) = %q; want %q", tt.code, got, tt.want)
			}
		})
	}
}

func TestCacheRoundTrip(t *testing.T) {
	c := &Cache{dir: t.TempDir(), ttl: time.Minute} // t.TempDir auto-cleans

	want := &Report{
		Location:    Location{Name: "Testville"},
		Temperature: 18.5,
		Conditions:  "Overcast",
		FetchedAt:   time.Now(),
	}
	if err := c.Put("Testville", want); err != nil {
		t.Fatalf("Put() error = %v", err)
	}

	got, ok := c.Get("Testville")
	if !ok {
		t.Fatal("Get() reported a miss right after Put()")
	}
	if got.Temperature != want.Temperature {
		t.Errorf("Temperature = %v; want %v", got.Temperature, want.Temperature)
	}
}

package main

import (
	"fmt"
	"sync"
)

type job struct{ n int }
type result struct{ n, square int }

func worker(id int, jobs <-chan job, results chan<- result, wg *sync.WaitGroup) {
	defer wg.Done()
	for j := range jobs { // exits automatically when jobs is closed and drained
		results <- result{n: j.n, square: j.n * j.n}
	}
}

func main() {
	const numWorkers = 3
	jobs := make(chan job, 10)
	results := make(chan result, 10)

	var wg sync.WaitGroup
	for w := 1; w <= numWorkers; w++ {
		wg.Add(1)
		go worker(w, jobs, results, &wg)
	}

	for n := 1; n <= 8; n++ {
		jobs <- job{n: n}
	}
	close(jobs) // signal: no more jobs -- workers finish their current item and exit

	go func() {
		wg.Wait()      // wait for every worker to stop sending
		close(results) // only safe to close AFTER all senders are done
	}()

	sum := 0
	for r := range results {
		sum += r.square
	}
	fmt.Println("sum of squares:", sum)
	// Output: sum of squares: 204
}

package main

import (
	"fmt"
	"sync"
)

func generator(n int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for i := 1; i <= n; i++ {
			out <- i
		}
	}()
	return out
}

// square is a pipeline stage. Running several of these against the SAME
// input channel is what makes this "fan-out".
func square(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in {
			out <- n * n
		}
	}()
	return out
}

// merge fans multiple channels back into one -- "fan-in".
func merge(cs ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(len(cs))
	for _, c := range cs {
		go func(c <-chan int) {
			defer wg.Done()
			for v := range c {
				out <- v
			}
		}(c)
	}
	go func() {
		wg.Wait()
		close(out)
	}()
	return out
}

func main() {
	in := generator(10)

	// three squarers pulling from the same channel -- fan-out
	c1 := square(in)
	c2 := square(in)
	c3 := square(in)

	sum := 0
	for v := range merge(c1, c2, c3) { // fan-in
		sum += v
	}
	fmt.Println("sum of squares 1..10:", sum)
	// Output: sum of squares 1..10: 385
}

package main

import "fmt"

func generate(nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for _, n := range nums {
			out <- n
		}
	}()
	return out
}

func double(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in {
			out <- n * 2
		}
	}()
	return out
}

func addOne(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in {
			out <- n + 1
		}
	}()
	return out
}

func main() {
	// Each stage runs concurrently -- addOne can start on item 1 while
	// double is still working on item 3.
	pipeline := addOne(double(generate(1, 2, 3, 4, 5)))
	for v := range pipeline {
		fmt.Print(v, " ")
	}
	fmt.Println()
	// Output: 3 5 7 9 11
}

