// Upper-bounded wildcard ("? extends Number") -- read-only access to any
// list of Number or its subclasses (Integer, Double, ...)
public static double sumAll(List<? extends Number> numbers) {
    double total = 0;
    for (Number n : numbers) {
        total += n.doubleValue();
    }
    return total;
}

