  const b = await delay(200, "settings");
  // total: ~400ms

  // Parallel — starts both immediately, waits for whichever is slower
  const [profile, settings] = await Promise.all([
    delay(200, "profile"),
    delay(200, "settings"),
  ]);
  // total: ~200ms

  return { a, b, profile, settings };
}

