    const book = { id: books.length + 1, title };
    books.push(book);
    res.status(201).json(book);
  });

  app.get("/books/:id", (req, res) => {
    const book = books.find((b) => b.id === Number(req.params.id));
    if (!book) return res.status(404).json({ error: "not found" });
    res.json(book);
  });

  return app;
}

