function sumWithLoop(n) {
  let total = 0;
  for (let i = 0; i < n; i += 1) {
    total += i;
  }
  return total;
}

function sumWithReduce(n) {
  return Array.from({ length: n }, (_, i) => i).reduce((a, b) => a + b, 0);
}

