from dotenv import load_dotenv
import anthropic, json

load_dotenv()
client = anthropic.Anthropic()
MODEL = "claude-sonnet-5"

TOOLS = [
    {
        "name": "calculator",
        "description": "Evaluate an arithmetic expression exactly. "
                       "Use this for ANY math instead of computing in your head.",
        "input_schema": {
            "type": "object",
            "properties": {
                "expression": {
                    "type": "string",
                    "description": "Expression using + - * / ** ( ), e.g. '17.5 * 12'",
                }
            },
            "required": ["expression"],
        },
    },
    {
        "name": "get_weather",
        "description": "Get current weather for a city.",
        "input_schema": {
            "type": "object",
            "properties": {
                "city": {"type": "string", "description": "City name, e.g. 'Paris'"},
                "unit": {"type": "string", "enum": ["celsius", "fahrenheit"]},
            },
            "required": ["city"],
        },
    },
]

import ast, operator

OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
       ast.Div: operator.truediv, ast.Pow: operator.pow, ast.USub: operator.neg}

def safe_eval(expr: str) -> float:
    """Evaluate arithmetic without eval() — never eval model output!"""
    def walk(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.BinOp) and type(node.op) in OPS:
            return OPS[type(node.op)](walk(node.left), walk(node.right))
        if isinstance(node, ast.UnaryOp) and type(node.op) in OPS:
            return OPS[type(node.op)](walk(node.operand))
        raise ValueError(f"unsupported syntax: {ast.dump(node)}")
    return walk(ast.parse(expr, mode="eval").body)

def get_weather(city: str, unit: str = "celsius") -> dict:
    # Real code would call a weather API; we fake it deterministically.
    fake_temp_c = (sum(map(ord, city.lower())) % 35)
    temp = fake_temp_c if unit == "celsius" else round(fake_temp_c * 9 / 5 + 32)
    return {"city": city, "temp": temp, "unit": unit, "conditions": "partly cloudy"}

def execute_tool(name: str, args: dict) -> str:
    try:
        if name == "calculator":
            return str(safe_eval(args["expression"]))
        if name == "get_weather":
            return json.dumps(get_weather(**args))
        return f"Error: unknown tool {name}"
    except Exception as e:
        return f"Error: {e}"      # return errors as text — the model can recover

def chat_with_tools(user_text: str) -> str:
    messages = [{"role": "user", "content": user_text}]

    while True:
        response = client.messages.create(
            model=MODEL, max_tokens=1000, tools=TOOLS, messages=messages,
        )

        if response.stop_reason != "tool_use":
            # Model is done — return its final text
            return next(b.text for b in response.content if b.type == "text")

        # 1. Echo the assistant turn (including its tool_use blocks) into history
        messages.append({"role": "assistant", "content": response.content})

        # 2. Execute every requested tool; collect ALL results in ONE user message
        results = []
        for block in response.content:
            if block.type == "tool_use":
                print(f"[tool] {block.name}({block.input})")
                output = execute_tool(block.name, block.input)
                results.append({
                    "type": "tool_result",
                    "tool_use_id": block.id,   # must match the request
                    "content": output,
                })
        messages.append({"role": "user", "content": results})
        # loop: the model now sees the results and continues


print(chat_with_tools(
    "If it's above 15°C in Madrid, what's 15% tip on a €84.60 dinner there?"
))
# [tool] get_weather({'city': 'Madrid'})
# [tool] calculator({'expression': '84.60 * 0.15'})
# "It's 22°C in Madrid, so... a 15% tip on €84.60 is €12.69."

MAX_TURNS = 10  # keep the last 10 user+assistant pairs

def truncated(messages: list[dict]) -> list[dict]:
    if len(messages) <= MAX_TURNS * 2:
        return messages
    kept = messages[-MAX_TURNS * 2:]
    # History must start with a "user" message — drop a leading assistant turn
    while kept and kept[0]["role"] == "assistant":
        kept = kept[1:]
    return kept

def summarize_turns(messages: list[dict]) -> str:
    transcript = "\n".join(
        f"{m['role']}: {m['content']}" for m in messages
        if isinstance(m["content"], str)
    )
    response = client.messages.create(
        model="claude-haiku-4-5",   # summarization is easy — use the cheap model
        max_tokens=400,
        messages=[{"role": "user", "content":
            "Summarize this conversation in under 150 words. Preserve all "
            "facts, names, numbers, preferences, and decisions:\n\n" + transcript}],
    )
    return response.content[0].text


class SummarizingConversation(Conversation):
    KEEP_RECENT = 6          # last 6 messages stay verbatim
    TRIGGER = 20             # summarize when history exceeds 20 messages

    def send(self, user_text: str) -> str:
        if len(self.messages) > self.TRIGGER:
            old, recent = self.messages[:-self.KEEP_RECENT], self.messages[-self.KEEP_RECENT:]
            summary = summarize_turns(old)
            self.messages = [
                {"role": "user", "content": f"<conversation_summary>{summary}</conversation_summary>"},
                {"role": "assistant", "content": "Understood — I have the context."},
                *recent,
            ]
        return super().send(user_text)

def build_system(profile: dict) -> str:
    return f"""You are a personal assistant.

<user_profile>
Name: {profile['name']}
Diet: {profile['diet']}
Timezone: {profile['tz']}
</user_profile>

Follow the profile silently; don't recite it."""

