def retrieve_confident(question: str, k: int = 3, max_distance: float = 0.8) -> list[dict]:
    hits = [h for h in retrieve(question, k) if h["distance"] <= max_distance]
    return hits   # may legitimately be empty!

hits = retrieve_confident("what is the meaning of life?")
if not hits:
    print("No relevant documents found.")   # ← the honest answer

def build_context(hits: list[dict]) -> str:
    """Format retrieved chunks into a numbered, source-tagged context block."""
    blocks = []
    for i, hit in enumerate(hits, start=1):
        src = hit["meta"].get("source", "unknown")
        blocks.append(f"[{i}] (source: {src})\n{hit['text']}")
    return "\n\n".join(blocks)

import anthropic

client = anthropic.Anthropic()   # reads ANTHROPIC_API_KEY from the environment

def generate(prompt: str) -> str:
    response = client.messages.create(
        model="claude-sonnet-5",
        max_tokens=1024,
        messages=[{"role": "user", "content": prompt}],
    )
    return "".join(block.text for block in response.content if block.type == "text")

def answer_question(question: str) -> str:
    hits = retrieve_confident(question, k=3, max_distance=0.8)
    if not hits:
        return "I don't know based on the available documents."
    return generate(build_prompt(question, hits))

