#!/usr/bin/env bash
# myappctl — start/stop/status wrapper around a long-running process
set -euo pipefail

PID_FILE="/var/run/myapp.pid"
APP_BIN="/opt/myapp/bin/myapp"

start() {
    if [[ -f "$PID_FILE" ]] && kill -0 "$(cat "$PID_FILE")" 2>/dev/null; then
        echo "already running (pid $(cat "$PID_FILE"))"
        exit 0
    fi
    nohup "$APP_BIN" > /var/log/myapp.log 2>&1 &
    echo $! > "$PID_FILE"
    echo "started (pid $!)"
}

stop() {
    if [[ -f "$PID_FILE" ]] && kill -0 "$(cat "$PID_FILE")" 2>/dev/null; then
        kill "$(cat "$PID_FILE")"
        rm -f "$PID_FILE"
        echo "stopped"
    else
        echo "not running"
    fi
}

status() {
    if [[ -f "$PID_FILE" ]] && kill -0 "$(cat "$PID_FILE")" 2>/dev/null; then
        echo "running (pid $(cat "$PID_FILE"))"
    else
        echo "stopped"
    fi
}

case "${1:-}" in
    start) start ;;
    stop) stop ;;
    status) status ;;
    restart) stop; start ;;
    *) echo "Usage: $0 {start|stop|status|restart}" >&2; exit 1 ;;
esac

LOG_FILE="${LOG_FILE:-/var/log/myscript.log}"

log() {
    local level="$1"; shift
    local message="$*"
    local timestamp
    timestamp=$(date -u +%Y-%m-%dT%H:%M:%SZ)
    printf '{"time":"%s","level":"%s","script":"%s","pid":%d,"msg":"%s"}\n' \
        "$timestamp" "$level" "$(basename "$0")" "$$" "$message" \
        | tee -a "$LOG_FILE"
}

log_info()  { log "info"  "$@"; }
log_warn()  { log "warn"  "$@"; }
log_error() { log "error" "$@"; }

log_info "starting job"
log_error "failed to connect to database"

LOG_LEVEL="${LOG_LEVEL:-info}"     # debug < info < warn < error

should_log() {
    local level="$1"
    case "$LOG_LEVEL" in
        debug) return 0 ;;
        info)  [[ "$level" != "debug" ]] ;;
        warn)  [[ "$level" == "warn" || "$level" == "error" ]] ;;
        error) [[ "$level" == "error" ]] ;;
    esac
}

log() {
    local level="$1"; shift
    should_log "$level" || return 0
    printf '{"time":"%s","level":"%s","msg":"%s"}\n' \
        "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$level" "$*" | tee -a "$LOG_FILE"
}

RUN_ID="${RUN_ID:-$(uuidgen 2>/dev/null || date +%s%N)}"

log() {
    local level="$1"; shift
    printf '{"time":"%s","level":"%s","run_id":"%s","msg":"%s"}\n' \
        "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$level" "$RUN_ID" "$*" | tee -a "$LOG_FILE"
}

notify_failure() {
    curl -fsS -X POST -H 'Content-Type: application/json' \
        -d "{\"text\":\"myscript failed — check logs (run_id=$RUN_ID)\"}" \
        "$ALERT_WEBHOOK_URL" >/dev/null || true
}

trap 'log_error "script failed at line $LINENO"; notify_failure' ERR

