func largest<T: Comparable>(_ items: [T]) -> T? {
    guard var current = items.first else { return nil }
    for item in items.dropFirst() where item > current {
        current = item
    }
    return current
}

print(largest([3, 7, 2, 9, 4]) ?? "empty")     // 9
print(largest(["pear", "apple", "kiwi"]) ?? "empty")   // pear

