export interface Notifier {
  send(to: string, message: string): Promise<boolean>;
}

export async function notifyAll(
  notifier: Notifier,
  recipients: string[],
  message: string
): Promise<number> {
  let successCount = 0;
  for (const to of recipients) {
    const sent = await notifier.send(to, message);
    if (sent) successCount += 1;
  }
  return successCount;
}

