function formatValue(value: string | string[] | undefined): string {
  if (typeof value === "undefined") {
    return "(none)";
  }
  if (typeof value === "string") {
    return value;
  }
  return value.join(", ");   // last remaining option: string[]
}

console.log(formatValue(undefined));           // (none)
