        print(f"Texting: {message}")


def notifier_factory(kind: str) -> Notifier:
    notifiers = {"email": EmailNotifier, "sms": SMSNotifier}
    try:
        return notifiers[kind]()
    except KeyError:
        raise ValueError(f"unknown notifier kind: {kind!r}")


